const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'workspaceId', 'userId', 'input', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

const brief = body.input;
if (!brief || brief.reportType !== 'manager_summary') {
  throw new Error('input.reportType doit valoir "manager_summary" pour ce workflow');
}
if (!brief.period || !brief.period.startDate || !brief.period.endDate) {
  throw new Error('input.period.startDate et endDate sont requis');
}
if (!brief.facts || typeof brief.facts !== 'object') {
  throw new Error('input.facts est requis — ce workflow ne calcule AUCUN fait (contrairement à report-activity-commercial/recruitment), il attend que Next.js les ait déjà assemblés via computeWeeklyBrief() avant l\'appel webhook.');
}

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    brief: brief,
    callbackUrl: body.callbackUrl,
  }
}];

// Pas de nœud "Hydrate Facts" ici (différence structurelle assumée avec
// report-activity-commercial/recruitment) : Next.js a déjà calculé le
// snapshot agenda + les faits business + le scoring déterministe
// weekly-scoring-v1 AVANT d'appeler ce webhook (voir
// src/app/api/reports/weekly-manager/trigger/route.ts). Ce nœud se contente
// donc d'assembler le prompt à partir de brief.facts, déjà complet.
const briefData = $('Validate Brief').item.json;
const brief = briefData.brief;
const facts = brief.facts;

const SYSTEM_PROMPT = `Tu rédiges le brief hebdomadaire de pilotage pour un manager d'ESN premium (Kredo Digital).
Ce document est lu le lundi matin : il doit permettre de savoir en 2 minutes ce qui exige une attention immédiate cette semaine.

RÈGLES ABSOLUES :
1. Tu reçois un dictionnaire de FAITS déjà calculés (JSON ci-dessous), incluant une liste "priorities" déjà triée et notée par un scoring déterministe (weekly-scoring-v1). Ce sont les SEULES données chiffrées et les SEULS éléments individuels que tu as le droit de citer. Tu ne dois JAMAIS inventer un chiffre, une date, un nom de compte/opportunité/mission absent des FAITS.
2. Le rang et le niveau (tier: critical/high/normal) de chaque item de facts.priorities sont déjà calculés — tu peux les commenter et les reformuler, jamais les recalculer ni les réordonner à ta guise.
3. Chaque élément de topPriorities doit OBLIGATOIREMENT reprendre le "title" exact d'un item présent dans facts.priorities — n'invente aucune priorité qui n'y figure pas.
4. Si une donnée est absente ou couverte par un caveat, dis-le explicitement plutôt que de combler le vide.
5. Style : direct, orienté décision, sans superlatifs creux — c'est un outil de pilotage, pas un rapport d'activité.

FORMAT DE SORTIE :
Réponds UNIQUEMENT en JSON valide, sans backticks, structure obligatoire :
{
  "executiveSummary": "3 à 5 lignes : l'essentiel de la semaine à retenir",
  "weeklyFocus": ["1 à 3 angles d'attention transverses pour la semaine"],
  "topPriorities": [
    { "title": "reprend EXACTEMENT le titre d'un item de facts.priorities", "whyNow": "pourquoi cet item est prioritaire cette semaine", "recommendedAction": "action concrète recommandée", "expectedImpact": "impact attendu si traité" }
  ],
  "risks": ["1 à 3 risques identifiés à partir des faits (marges, comptes silencieux, retards)"],
  "suggestedTasks": [
    { "title": "titre de tâche actionnable", "description": "description courte", "dueAt": "date ISO ou null", "priority": "urgent|high|normal|low", "entityType": "optionnel, ex: opportunity", "entityId": "optionnel" }
  ],
  "warnings": ["avertissement si une section manque de données"]
}`;

const detailLevel = brief.detailLevel || 'standard';
const scopeLabel = (brief.scope && brief.scope.isWorkspaceWide) ? 'Ensemble du workspace' : 'Périmètre personnel';
const instructions = brief.additionalInstructions || '(aucune)';

const userPrompt = `PÉRIMÈTRE : ${scopeLabel}
NIVEAU DE DÉTAIL DEMANDÉ : ${detailLevel}
INSTRUCTIONS COMPLÉMENTAIRES : ${instructions}

FAITS (source unique de vérité — JSON, priorities déjà triées par rang décroissant) :
${JSON.stringify(facts, null, 2)}`;

return [{
  json: {
    ...briefData,
    facts,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt,
  }
}];

