const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Réponse LLM non-JSON : ' + content.slice(0, 200));
}

if (!parsed.executiveSummary || parsed.executiveSummary.length < 20) {
  throw new Error('executiveSummary vide ou trop courte');
}
if (!Array.isArray(parsed.weeklyFocus) || !Array.isArray(parsed.topPriorities) || !Array.isArray(parsed.risks) || !Array.isArray(parsed.suggestedTasks)) {
  throw new Error('weeklyFocus, topPriorities, risks ou suggestedTasks manquant/invalide');
}

const validPriorities = ['urgent', 'high', 'normal', 'low'];
for (const task of parsed.suggestedTasks) {
  if (!task || !task.title || !validPriorities.includes(task.priority)) {
    throw new Error('Une suggestedTask est invalide (title ou priority manquant/incorrect)');
  }
}
for (const priority of parsed.topPriorities) {
  if (!priority || !priority.title || !priority.recommendedAction) {
    throw new Error('Un topPriority est invalide (title ou recommendedAction manquant)');
  }
}

return [{
  json: {
    ...upstream,
    narrative: parsed,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

// Contrôle "chiffres non autorisés" : tout nombre à 2+ chiffres cité dans la
// narration doit apparaître quelque part dans les FAITS sérialisés (même
// technique que report-activity-commercial/recruitment).
const data = $input.first().json;
const narrative = data.narrative;
const factsStr = JSON.stringify(data.facts);
const qaFlags = [];

const narrativeText = [
  narrative.executiveSummary,
  ...(Array.isArray(narrative.weeklyFocus) ? narrative.weeklyFocus : []),
  ...(Array.isArray(narrative.topPriorities) ? narrative.topPriorities.map((p) => `${p.title} ${p.whyNow} ${p.recommendedAction} ${p.expectedImpact}`) : []),
  ...(Array.isArray(narrative.risks) ? narrative.risks : []),
  ...(Array.isArray(narrative.warnings) ? narrative.warnings : []),
].filter(Boolean).join(' ');

const numbers = narrativeText.match(/\d{2,}/g) || [];
const unauthorized = numbers.filter((n) => !factsStr.includes(n));
if (unauthorized.length > 0) {
  qaFlags.push({ check: 'no_unauthorized_numbers', passed: false, detail: `Nombres absents des FAITS : ${unauthorized.join(', ')}` });
} else {
  qaFlags.push({ check: 'no_unauthorized_numbers', passed: true });
}

const summaryWordCount = (narrative.executiveSummary || '').split(/\s+/).filter(Boolean).length;
if (summaryWordCount < 15 || summaryWordCount > 120) {
  qaFlags.push({ check: 'summary_length', passed: false, detail: `${summaryWordCount} mots (attendu 15-120)` });
} else {
  qaFlags.push({ check: 'summary_length', passed: true, detail: `${summaryWordCount} mots` });
}

const topPrioritiesCount = Array.isArray(narrative.topPriorities) ? narrative.topPriorities.length : 0;
if (topPrioritiesCount < 1 || topPrioritiesCount > 5) {
  qaFlags.push({ check: 'top_priorities_count', passed: false, detail: `${topPrioritiesCount} (attendu 1-5)` });
} else {
  qaFlags.push({ check: 'top_priorities_count', passed: true, detail: `${topPrioritiesCount}` });
}

// Traçabilité : chaque topPriority doit reprendre un titre déjà présent dans
// facts.priorities — vérifie que le LLM n'a rien inventé (règle 3 du prompt).
const knownTitles = Array.isArray(data.facts.priorities) ? data.facts.priorities.map((p) => p.title) : [];
const unknownTopPriorities = (Array.isArray(narrative.topPriorities) ? narrative.topPriorities : [])
  .map((p) => p.title)
  .filter((title) => !knownTitles.includes(title));
if (unknownTopPriorities.length > 0) {
  qaFlags.push({ check: 'top_priorities_traceability', passed: false, detail: `Titres absents de facts.priorities : ${unknownTopPriorities.join(', ')}` });
} else {
  qaFlags.push({ check: 'top_priorities_traceability', passed: true });
}

if (data.facts.caveats && data.facts.caveats.length > 0) {
  qaFlags.push({ check: 'data_coverage_caveats', passed: true, detail: data.facts.caveats.join(' | ') });
}

return [{ json: { ...data, qaFlags } }];

const data = $input.first().json;

const contentJson = {
  facts: data.facts,
  narrative: data.narrative,
  sourceRefs: (data.facts.priorities || []).slice(0, 10).map((p) => ({ entityType: p.entityType || p.sourceType, entityId: p.entityId || p.sourceId, label: p.title })),
  qaFlags: data.qaFlags || [],
};

const warnings = Array.isArray(data.narrative.warnings)
  ? data.narrative.warnings.filter((w) => typeof w === 'string' && w.trim().length > 0)
  : [];
const period = data.facts.period || {};
const contentTextParts = [
  `# Brief hebdomadaire — Semaine ${period.weekIso || ''} (${period.startDate || ''} → ${period.endDate || ''})`,
  data.narrative.executiveSummary,
  Array.isArray(data.narrative.weeklyFocus) && data.narrative.weeklyFocus.length > 0
    ? `Focus de la semaine : ${data.narrative.weeklyFocus.join(' | ')}`
    : null,
  Array.isArray(data.narrative.topPriorities) && data.narrative.topPriorities.length > 0
    ? `Priorités : ${data.narrative.topPriorities.map((p) => p.title).join(' | ')}`
    : null,
  Array.isArray(data.narrative.risks) && data.narrative.risks.length > 0
    ? `Risques : ${data.narrative.risks.join(' | ')}`
    : null,
  warnings.length > 0 ? `Warnings : ${warnings.join(' | ')}` : null,
].filter((value) => typeof value === 'string' && value.trim().length > 0);

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId: data.runId,
  phase: 1,
  resultType: 'manager_summary',
  status: 'succeeded',
  contentJson,
  contentText: contentTextParts.join('\n\n'),
  title: `Brief hebdomadaire — Semaine ${period.weekIso || ''}`,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.facts,
  sourceRefs: contentJson.sourceRefs,
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

try {
  const vb = $('Validate Brief').item.json;
  runId = vb.runId || null;
  callbackUrl = vb.callbackUrl || null;
} catch (e) {
  // Validate Brief n'a produit aucune sortie exploitable — notification impossible.
}

let errorMessage = 'Erreur inconnue dans le workflow report-manager-summary';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId,
  phase: 1,
  resultType: 'manager_summary',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
